Here's a function in JavaScript that takes an array of 5 numbers as input and checks if any of the numbers is a valid prime number, if it is print the number to the console:

```
function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) {
      return false;
    }
  }
  return true;
}

function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    if (isPrime(arr[i])) {
      console.log(arr[i]);
    }
  }
}
```

To use this function, you can call it with an array of 5 numbers as input:

```
checkPrime([2, 3, 5, 7, 11]);
```

This will print the numbers 2, 3, 5, 7, and 11 to the console.

